13	function firstChild(
14	  node: SyntaxNode,
15	  grammarName: string | string[],
16	): SyntaxNode | null {
17	  if (Array.isArray(grammarName)) {
18	    return (
19	      node.children.find((child) => grammarName.includes(child.type)) || null
20	    );
21	  }
22	  return node.children.find((child) => child.type === grammarName) || null;
23	}
24	
25	function collapseChildren(
26	  node: SyntaxNode,
27	  code: string,
28	  blockTypes: string[],
29	  collapseTypes: string[],
30	  collapseBlockTypes: string[],
31	  maxChunkSize: number,
32	): string {
33	  code = code.slice(0, node.endIndex);
34	  const block = firstChild(node, blockTypes);
35	  const collapsedChildren = [];
36	
37	  if (block) {
38	    const childrenToCollapse = block.children.filter((child) =>
39	      collapseTypes.includes(child.type),
40	    );
41	    for (const child of childrenToCollapse.reverse()) {
42	      const grandChild = firstChild(child, collapseBlockTypes);
43	      if (grandChild) {
44	        const start = grandChild.startIndex;
45	        const end = grandChild.endIndex;
46	        const collapsedChild =
47	          code.slice(child.startIndex, start) +
48	          collapsedReplacement(grandChild);
49	        code =
50	          code.slice(0, start) +
51	          collapsedReplacement(grandChild) +
52	          code.slice(end);
53	
54	        collapsedChildren.unshift(collapsedChild);
55	      }
56	    }
57	  }
58	  code = code.slice(node.startIndex);
59	  let removedChild = false;
60	  while (countTokens(code) > maxChunkSize && collapsedChildren.length > 0) {
61	    removedChild = true;
62	    // Remove children starting at the end - TODO: Add multiple chunks so no children are missing
63	    const childCode = collapsedChildren.pop()!;
64	    const index = code.lastIndexOf(childCode);
65	    if (index > 0) {
66	      code = code.slice(0, index) + code.slice(index + childCode.length);
67	    }
68	  }
69	
70	  if (removedChild) {
71	    // Remove the extra blank lines
72	    let lines = code.split("\n");
73	    let firstWhiteSpaceInGroup = -1;
74	    for (let i = lines.length - 1; i >= 0; i--) {
75	      if (lines[i].trim() === "") {
76	        if (firstWhiteSpaceInGroup < 0) {
77	          firstWhiteSpaceInGroup = i;
78	        }
79	      } else {
80	        if (firstWhiteSpaceInGroup - i > 1) {
81	          // Remove the lines
82	          lines = [
83	            ...lines.slice(0, i + 1),
84	            ...lines.slice(firstWhiteSpaceInGroup + 1),
85	          ];
86	        }
87	        firstWhiteSpaceInGroup = -1;
88	      }
89	    }
90	
91	    code = lines.join("\n");
92	  }
93	
94	  return code;
95	}
