97	export const FUNCTION_BLOCK_NODE_TYPES = ["block", "statement_block"];
98	export const FUNCTION_DECLARATION_NODE_TYPEs = [
99	  "method_definition",
100	  "function_definition",
101	  "function_item",
102	  "function_declaration",
103	  "method_declaration",
104	];
105	
106	function constructClassDefinitionChunk(
107	  node: SyntaxNode,
108	  code: string,
109	  maxChunkSize: number,
110	): string {
111	  return collapseChildren(
112	    node,
113	    code,
114	    ["block", "class_body", "declaration_list"],
115	    FUNCTION_DECLARATION_NODE_TYPEs,
116	    FUNCTION_BLOCK_NODE_TYPES,
117	    maxChunkSize,
118	  );
119	}
120	
121	function constructFunctionDefinitionChunk(
122	  node: SyntaxNode,
123	  code: string,
124	  maxChunkSize: number,
125	): string {
126	  const bodyNode = node.children[node.children.length - 1];
127	  const funcText =
128	    code.slice(node.startIndex, bodyNode.startIndex) +
129	    collapsedReplacement(bodyNode);
130	
131	  if (
132	    node.parent &&
133	    ["block", "declaration_list"].includes(node.parent.type) &&
134	    node.parent.parent &&
135	    ["class_definition", "impl_item"].includes(node.parent.parent.type)
136	  ) {
137	    // If inside a class, include the class header
138	    const classNode = node.parent.parent;
139	    const classBlock = node.parent;
140	    return `${code.slice(
141	      classNode.startIndex,
142	      classBlock.startIndex,
143	    )}...\n\n${" ".repeat(node.startPosition.column)}${funcText}`;
144	  }
145	  return funcText;
146	}
147	
148	const collapsedNodeConstructors: {
149	  [key: string]: (
150	    node: SyntaxNode,
151	    code: string,
152	    maxChunkSize: number,
153	  ) => string;
154	} = {
155	  // Classes, structs, etc
156	  class_definition: constructClassDefinitionChunk,
157	  class_declaration: constructClassDefinitionChunk,
158	  impl_item: constructClassDefinitionChunk,
159	  // Functions
160	  function_definition: constructFunctionDefinitionChunk,
161	  function_declaration: constructFunctionDefinitionChunk,
162	  function_item: constructFunctionDefinitionChunk,
163	};
164	
165	function* getSmartCollapsedChunks(
166	  node: SyntaxNode,
167	  code: string,
168	  maxChunkSize: number,
169	  root = true,
170	): Generator<ChunkWithoutID> {
171	  // Keep entire text if not over size
172	  if (
173	    (root || node.type in collapsedNodeConstructors) &&
174	    countTokens(node.text) < maxChunkSize
175	  ) {
176	    yield {
177	      content: node.text,
178	      startLine: node.startPosition.row,
179	      endLine: node.endPosition.row,
180	    };
181	    return;
182	  }
183	
184	  // If a collapsed form is defined, use that
185	  if (node.type in collapsedNodeConstructors) {
186	    yield {
187	      content: collapsedNodeConstructors[node.type](node, code, maxChunkSize),
188	      startLine: node.startPosition.row,
189	      endLine: node.endPosition.row,
190	    };
191	  }
192	
193	  // Recurse (because even if collapsed version was shown, want to show the children in full somewhere)
194	  for (const child of node.children) {
195	    yield* getSmartCollapsedChunks(child, code, maxChunkSize, false);
196	  }
197	}
198	
199	export async function* codeChunker(
200	  filepath: string,
201	  contents: string,
202	  maxChunkSize: number,
203	): AsyncGenerator<ChunkWithoutID> {
204	  if (contents.trim().length === 0) {
205	    return;
206	  }
207	
208	  const parser = await getParserForFile(filepath);
209	  if (parser === undefined) {
210	    console.warn(`Failed to load parser for file ${filepath}: `);
211	    return;
212	  }
213	
214	  const tree = parser.parse(contents);
215	
216	  yield* getSmartCollapsedChunks(tree.rootNode, contents, maxChunkSize);
217	}
